 ('POST','/api/v1/auth/register','Identity','Anonymous',{'email':'customer@example.test','password':'Example-test-password-123','fullName':'TV customer'},{'userId':guid},'10–128 password characters; normalized unique email; role fixed CUSTOMER; duplicate 409; rate protection at Gateway.'),
 ('POST','/api/v1/auth/login','Identity','Anonymous',{'email':'customer@example.test','password':'Example-test-password-123'},{'accessToken':'<JWT>','expiresAt':'2026-10-07T02:15:00Z'},'401 wrong credentials/locked/inactive; 15 minute token; no refresh/recovery workflow yet.'),
 ('POST','/api/v1/staff-assignments','Identity','Current ADMIN',{'lotId':guid,'userId':'22222222-2222-4222-8222-222222222222','role':'PARKING_STAFF','activeFrom':'2026-10-07T00:00:00Z','activeTo':None,'canManageStaffAssignments':False},{'assignmentId':guid},'Parking catalog validates lot by gRPC; user FK local Identity. Role Staff/Manager only. Delegated-manager write APIs are not implemented.'),
 ('GET','/api/v1/parking-lots','Parking','Anonymous',None,[{'id':guid,'code':'LOT-A','name':'Bãi A','address':'Địa chỉ mẫu','latitude':10.7,'longitude':106.6,'timezone':'Asia/Ho_Chi_Minh'}],'No user/plate/audit PII. Active lots only; no search endpoint in this release.'),
 ('POST','/api/v1/bookings','Parking','JWT current active user + verified vehicle access',{'lotId':guid,'slotId':'33333333-3333-4333-8333-333333333333','vehicleId':'44444444-4444-4444-8444-444444444444','startsAt':'2026-10-07T02:00:00Z','endsAt':'2026-10-07T04:00:00Z'},{'id':guid,'code':'B...','status':'PENDING_PAYMENT','estimatedAmount':60000,'holdExpiresAt':'2026-10-07T01:15:00Z','version':1},'Idempotency-Key required. EXACT_SLOT only; time/policy/opening/closure/physical occupancy/vehicle compatibility checks, locks + GiST. Only one FLAT_BLOCK price rule supported; other pricing plans fail 409. No QR before verified payment.'),
 ('POST','/api/v1/parking-lots/{lotId}/plate-recognitions','Parking → AI','JWT + current lot OCR permission',{'imageBase64':'<PNG-or-JPEG-base64>','contentType':'image/png'},{'id':guid,'status':'PENDING_REVIEW','candidatePlate':'51A12345','confidence':0.95,'modelVersion':'<configured-provider>'},'Idempotency-Key <=128, image <=4 MiB with signature validation. 401 no token,403 wrong scope,400 bad image,409 changed payload/key,503 no/failing provider. No automatic gate/financial action.'),
 ('POST','/api/v1/payments','Payment → Parking quote','JWT + booking owner or current assigned Staff',{'bookingId':guid,'method':'CASH'},{'id':guid,'lotId':guid,'bookingId':guid,'amount':60000,'currency':'VND','method':'CASH','status':'PENDING','version':1},'Idempotency-Key required, amount from Parking only. VNPAY returns 503 until verified adapter is implemented. Booking currently payable and hold valid for a new request.'),
 ('POST','/api/v1/parking-lots/{lotId}/payments/{paymentId}/cash-confirmation','Payment','JWT + current assigned PARKING_STAFF CASH permission',{'version':1,'reason':'Đã nhận tiền mặt và đối chiếu booking'},{'id':guid,'lotId':guid,'bookingId':guid,'amount':60000,'currency':'VND','method':'CASH','status':'SUCCESS','version':2},'Actor server-derived; 403 Customer/Manager without Staff assignment,409 wrong version/state. Successful receipt and outbox atomic. Repeated SUCCESS confirmation returns existing result, no new event. Not physical exit.'),
